@push('scripts')
<script>
(() => { const slider = document.querySelector('.hero-slider'); if (!slider) return; const slides = [...slider.querySelectorAll('.hero-slide')]; let current = 0; const show = (index) => { current = (index + slides.length) % slides.length; slides.forEach((slide, i) => slide.classList.toggle('hero-slide-active', i === current)); }; slider.querySelector('.hero-next').onclick = () => show(current + 1); slider.querySelector('.hero-prev').onclick = () => show(current - 1); setInterval(() => show(current + 1), Number(slider.dataset.autoplay)); })();
</script>
